@java.lang.Override
protected void doPost(javax.servlet.http.HttpServletRequest request, javax.servlet.http.HttpServletResponse response) {
    java.lang.String username = com.coveros.training.helpers.StringUtils.makeNotNullable(request.getParameter(com.coveros.training.authentication.RegisterServlet.USERNAME_PARAM));
    request.setAttribute(com.coveros.training.authentication.RegisterServlet.USERNAME_PARAM, username);
    java.lang.String password = com.coveros.training.helpers.StringUtils.makeNotNullable(request.getParameter(com.coveros.training.authentication.RegisterServlet.PASSWORD_PARAM));
    request.setAttribute(com.coveros.training.authentication.RegisterServlet.PASSWORD_PARAM, password);
    java.lang.String responseText;
    if (username.isEmpty()) {
        responseText = "no username provided";
    } else if (password.isEmpty()) {
        responseText = "no password provided";
    } else {
        com.coveros.training.authentication.RegisterServlet.logger.info("received request to register a user, {}", username);
        com.coveros.training.authentication.domainobjects.RegistrationResult registrationResult = com.coveros.training.authentication.RegisterServlet.registrationUtils.processRegistration(username, password);
        responseText = registrationResult.toPrettyString();
    }
    request.setAttribute("result", responseText);
    request.setAttribute("return_page", "library.html");
    forwardToResult(request, response, com.coveros.training.authentication.RegisterServlet.logger);
}

/**
 * Wrapping a static method call for testing.
 */
private void forwardToResult(javax.servlet.http.HttpServletRequest request, javax.servlet.http.HttpServletResponse response, org.slf4j.Logger logger) {
    com.coveros.training.helpers.ServletUtils.forwardToResult(request, response, logger);
}

