/**
 * A business process to evaluate an attempt to register a new user.
 * <ol>
 * <li>Make sure the username and password aren't null or empty</li>
 * <li>Make sure the user isn't already in the database</li>
 * <li>Check if the password is sufficiently complex to be secure</li>
 * <li>Create a new account for this user, saving the user's credentials</li>
 * </ol>
 */
public com.coveros.training.authentication.domainobjects.RegistrationResult processRegistration(java.lang.String username, java.lang.String password) {
    com.coveros.training.authentication.RegistrationUtils.logger.info("Starting registration");
    com.coveros.training.helpers.CheckUtils.StringMustNotBeNullOrEmpty(username);
    com.coveros.training.helpers.CheckUtils.StringMustNotBeNullOrEmpty(password);
    if (isUserInDatabase(username)) {
        com.coveros.training.authentication.RegistrationUtils.logger.info("cannot register this user - they are already registered");
        return new com.coveros.training.authentication.domainobjects.RegistrationResult(false, com.coveros.training.authentication.domainobjects.RegistrationStatusEnums.ALREADY_REGISTERED);
    }
    // at this point we know the user is not yet registered in the database
    // then we check if the password is good.
    final com.coveros.training.authentication.domainobjects.PasswordResult passwordResult = com.coveros.training.authentication.RegistrationUtils.isPasswordGood(password);
    if (passwordResult.status != com.coveros.training.authentication.domainobjects.PasswordResultEnums.SUCCESS) {
        com.coveros.training.authentication.RegistrationUtils.logger.info("user provided a bad password during registration");
        return new com.coveros.training.authentication.domainobjects.RegistrationResult(false, com.coveros.training.authentication.domainobjects.RegistrationStatusEnums.BAD_PASSWORD, passwordResult.toPrettyString());
    }
    // at this point, we feel assured it's ok to save to the database.
    saveToDatabase(username, password);
    com.coveros.training.authentication.RegistrationUtils.logger.info("saving new user, {}, to database", username);
    return new com.coveros.training.authentication.domainobjects.RegistrationResult(true, com.coveros.training.authentication.domainobjects.RegistrationStatusEnums.SUCCESSFULLY_REGISTERED);
}

/**
 * Whether we qualify a password as good.
 *
 * <p>
 * To summarize - we check the following here:
 * </p>
 * <ol>
 * <li>The password must not be empty</li>
 * <li>it must not be too short (less than 6 characters)</li>
 * <li>it cannot be too long (more than 100 characters - this is because the framework</li>
 * <li>analysis slows to a crawl with more than 100 characters)</li>
 * <li>Whether the entropy framework we're using considers the password good.</li>
 * </ol>
 * <p>See {@link PasswordResult}</p>
 */
public static com.coveros.training.authentication.domainobjects.PasswordResult isPasswordGood(java.lang.String password) {
    if (password.isEmpty()) {
        com.coveros.training.authentication.RegistrationUtils.logger.info("password was empty");
        return com.coveros.training.authentication.domainobjects.PasswordResult.createDefault(com.coveros.training.authentication.domainobjects.PasswordResultEnums.EMPTY_PASSWORD);
    }
    com.coveros.training.helpers.CheckUtils.StringMustNotBeNullOrEmpty(password);
    final boolean isTooSmall = password.length() < 10;
    if (isTooSmall) {
        com.coveros.training.authentication.RegistrationUtils.logger.info("password was too short");
        return com.coveros.training.authentication.domainobjects.PasswordResult.createDefault(com.coveros.training.authentication.domainobjects.PasswordResultEnums.TOO_SHORT);
    }
    com.coveros.training.helpers.CheckUtils.mustBeTrueAtThisPoint(isTooSmall == false, "At this point, the password cannot be too small");
    final boolean isTooLarge = password.length() > 100;
    if (isTooLarge) {
        com.coveros.training.authentication.RegistrationUtils.logger.info("password was too long");
        return com.coveros.training.authentication.domainobjects.PasswordResult.createDefault(com.coveros.training.authentication.domainobjects.PasswordResultEnums.TOO_LONG);
    }
    com.coveros.training.helpers.CheckUtils.mustBeTrueAtThisPoint(isTooLarge == false, "At this point, the password cannot be too large");
    // Nbvcxz is a tool that tests entropy on passwords
    // See github.com/GoSimpleLLC/nbvcxz
    final me.gosimple.nbvcxz.Nbvcxz nbvcxz = new me.gosimple.nbvcxz.Nbvcxz();
    final me.gosimple.nbvcxz.scoring.Result result = nbvcxz.estimate(password);
    final java.lang.String suggestions = java.lang.String.join(";", result.getFeedback().getSuggestion());
    final java.lang.Double entropy = result.getEntropy();
    com.coveros.training.helpers.CheckUtils.mustBeTrueAtThisPoint(entropy > 0.0, "There must be *some* entropy at this point, more than 0");
    java.lang.String timeToCrackOff = me.gosimple.nbvcxz.scoring.TimeEstimate.getTimeToCrackFormatted(result, "OFFLINE_BCRYPT_12");
    java.lang.String timeToCrackOn = me.gosimple.nbvcxz.scoring.TimeEstimate.getTimeToCrackFormatted(result, "ONLINE_THROTTLED");
    if (!result.isMinimumEntropyMet()) {
        com.coveros.training.authentication.RegistrationUtils.logger.info("minimum entropy for password was not met");
        return new com.coveros.training.authentication.domainobjects.PasswordResult(com.coveros.training.authentication.domainobjects.PasswordResultEnums.INSUFFICIENT_ENTROPY, entropy, timeToCrackOff, timeToCrackOn, suggestions);
    } else {
        com.coveros.training.authentication.RegistrationUtils.logger.info("password met required entropy");
        return new com.coveros.training.authentication.domainobjects.PasswordResult(com.coveros.training.authentication.domainobjects.PasswordResultEnums.SUCCESS, entropy, timeToCrackOff, timeToCrackOn, result.getFeedback().getResult());
    }
}

private void saveToDatabase(java.lang.String username, java.lang.String password) {
    final long userId = persistenceLayer.saveNewUser(username);
    persistenceLayer.updateUserWithPassword(userId, password);
}

