public void serverStart() {
    int portNumber = 8000;
    while (shouldRepeat) {
        try (java.net.ServerSocket serverSocket = new java.net.ServerSocket(portNumber);java.net.Socket clientSocket = serverSocket.accept()) {
            java.io.PrintWriter out = new java.io.PrintWriter(clientSocket.getOutputStream(), true);
            java.io.BufferedReader in = new java.io.BufferedReader(new java.io.InputStreamReader(clientSocket.getInputStream()));
            java.lang.String inputLine;
            while ((inputLine = in.readLine()) != null) {
                java.lang.String result = "OK";
                final java.lang.String[] inputTokens = java.util.Arrays.stream(inputLine.split(" ")).map(java.lang.String::toLowerCase).toArray(java.lang.String[]::new);
                try {
                    handleQuit(inputTokens);
                    handleSetCases(inputTokens);
                    result = handleGetCases(result, inputTokens);
                    handleClickActions(inputTokens);
                } catch (java.lang.Exception ex) {
                    com.coveros.training.autoinsurance.AutoInsuranceScriptServer.logger.error(ex.getMessage());
                    result = "FAILURE";
                }
                out.println(result);
            } 
        } catch (java.io.IOException e) {
            com.coveros.training.autoinsurance.AutoInsuranceScriptServer.logger.error(("Exception caught when trying to listen on port " + portNumber) + " or listening for a connection");
            com.coveros.training.autoinsurance.AutoInsuranceScriptServer.logger.error(e.getMessage());
        }
    } 
}

