    claimsCalcButton = addClaimsCalcButton(box);
    claimsCalcButton.addActionListener(e -> {
        final int intPreviousClaims = getIntPreviousClaims();
        final java.lang.String customerAge = ageField.getText();
        final int intCustomerAge = java.lang.Integer.parseInt(customerAge);
        final com.coveros.training.autoinsurance.AutoInsuranceAction result = com.coveros.training.autoinsurance.AutoInsuranceProcessor.process(intPreviousClaims, intCustomerAge);
        setLabel((((("Premium increase: $" + result.premiumIncreaseDollars) + " Warning Ltr: ") + result.warningLetterEnum) + " is canceled: ") + result.isPolicyCanceled);
    });
    return box;
}

