    final java.lang.String numberPreviousClaims = ((java.lang.String) (claimsDropDown.getSelectedItem()));
    assert numberPreviousClaims != null;
    switch (numberPreviousClaims) {
        case "0" :
            return 0;
        case "1" :
            return 1;
        case "2-4" :
            return 2;
        case ">=5" :
            return 5;
