@java.lang.Override
protected void doGet(javax.servlet.http.HttpServletRequest request, javax.servlet.http.HttpServletResponse response) {
    final java.util.List<com.coveros.training.library.domainobjects.Book> books = com.coveros.training.library.LibraryBookListAvailableServlet.libraryUtils.listAvailableBooks();
    com.coveros.training.library.LibraryBookListAvailableServlet.logger.info("Received request for all available books");
    java.lang.String result;
    if (books.isEmpty()) {
        result = "No books exist in the database";
    } else {
        final java.lang.String allBooks = books.stream().map(com.coveros.training.library.domainobjects.Book::toOutputString).collect(java.util.stream.Collectors.joining(","));
        result = ("[" + allBooks) + "]";
    }
    request.setAttribute(com.coveros.training.library.LibraryBookListAvailableServlet.RESULT, result);
    com.coveros.training.helpers.ServletUtils.forwardToRestfulResult(request, response, com.coveros.training.library.LibraryBookListAvailableServlet.logger);
}

