/**
 * Register a new book with the library
 *
 * @param bookTitle
 * 		the title of a book
 * @return an enum {@link LibraryActionResults} indicating the resultant status
 */
public com.coveros.training.library.domainobjects.LibraryActionResults registerBook(java.lang.String bookTitle) {
    if (bookTitle.isEmpty()) {
        throw new java.lang.IllegalArgumentException("bookTitle was an empty string - disallowed when registering books");
    }
    com.coveros.training.library.LibraryUtils.logger.info("trying to register a book with title: {}", bookTitle);
    final com.coveros.training.library.domainobjects.Book book = searchForBookByTitle(bookTitle);
    if (!book.isEmpty()) {
        com.coveros.training.library.LibraryUtils.logger.info("book: {} was already registered", bookTitle);
        return com.coveros.training.library.domainobjects.LibraryActionResults.ALREADY_REGISTERED_BOOK;
    }
    com.coveros.training.library.LibraryUtils.logger.info("book: {} was not found.  Registering new book...", bookTitle);
    saveNewBook(bookTitle);
    return com.coveros.training.library.domainobjects.LibraryActionResults.SUCCESS;
}

public com.coveros.training.library.domainobjects.LibraryActionResults deleteBorrower(com.coveros.training.library.domainobjects.Borrower borrower) {
    com.coveros.training.library.LibraryUtils.logger.info("deleting a borrower.  id: {}, name: {}", borrower.id, borrower.name);
    final com.coveros.training.library.domainobjects.Borrower borrowerInDatabase = searchForBorrowerByName(borrower.name);
    if (borrowerInDatabase.isEmpty()) {
        com.coveros.training.library.LibraryUtils.logger.info("borrower not found in database.  Therefore, obviously, cannot be deleted");
        return com.coveros.training.library.domainobjects.LibraryActionResults.NON_REGISTERED_BORROWER_CANNOT_BE_DELETED;
    }
    persistence.deleteBorrower(borrower.id);
    com.coveros.training.library.LibraryUtils.logger.info("borrower with name: {} and id: {} was deleted", borrowerInDatabase.name, borrowerInDatabase.id);
    return com.coveros.training.library.domainobjects.LibraryActionResults.SUCCESS;
}

public java.util.List<com.coveros.training.library.domainobjects.Loan> searchForLoanByBorrower(com.coveros.training.library.domainobjects.Borrower borrower) {
    com.coveros.training.library.LibraryUtils.logger.info("searching for loan by borrower with name: {}", borrower.name);
    return persistence.searchForLoanByBorrower(borrower).orElse(new java.util.ArrayList<>());
}

public java.util.List<com.coveros.training.library.domainobjects.Book> listAvailableBooks() {
    com.coveros.training.library.LibraryUtils.logger.info("received request to list available books");
    return persistence.listAvailableBooks().orElse(new java.util.ArrayList<>());
}

public com.coveros.training.library.domainobjects.LibraryActionResults deleteBook(com.coveros.training.library.domainobjects.Book book) {
    com.coveros.training.library.LibraryUtils.logger.info("deleting a book.  id: {}, title: {}", book.id, book.title);
    final com.coveros.training.library.domainobjects.Book bookInDatabase = searchForBookByTitle(book.title);
    if (bookInDatabase.isEmpty()) {
        com.coveros.training.library.LibraryUtils.logger.info("book not found in database.  Therefore, obviously, cannot be deleted");
        return com.coveros.training.library.domainobjects.LibraryActionResults.NON_REGISTERED_BOOK_CANNOT_BE_DELETED;
    }
    persistence.deleteBook(book.id);
    com.coveros.training.library.LibraryUtils.logger.info("book with title: {} and id: {} was deleted", bookInDatabase.title, bookInDatabase.id);
    return com.coveros.training.library.domainobjects.LibraryActionResults.SUCCESS;
}

