/**
 * Lend a book to a borrower.
 *
 * @param bookTitle
 * 		The title of a registered book, e.g. see {@link #registerBook(String)}
 * @param borrowerName
 * 		the name of a registered borrower, e.g. see {@link #registerBorrower(String)}
 * @param borrowDate
 * 		the date the book is being lent out.
 * @return an enum {@link LibraryActionResults} indicating the resultant status
 */
public com.coveros.training.library.domainobjects.LibraryActionResults lendBook(java.lang.String bookTitle, java.lang.String borrowerName, java.sql.Date borrowDate) {
    com.coveros.training.library.LibraryUtils.logger.info("starting process to lend a book: {} to borrower: {}", bookTitle, borrowerName);
    final com.coveros.training.library.domainobjects.Book book = searchForBookByTitle(bookTitle);
    final com.coveros.training.library.domainobjects.Book foundBook = new com.coveros.training.library.domainobjects.Book(book.id, bookTitle);
    final com.coveros.training.library.domainobjects.Borrower borrower = searchForBorrowerByName(borrowerName);
    final com.coveros.training.library.domainobjects.Borrower foundBorrower = new com.coveros.training.library.domainobjects.Borrower(borrower.id, borrowerName);
    return lendBook(foundBook, foundBorrower, borrowDate);
}

public com.coveros.training.library.domainobjects.LibraryActionResults lendBook(com.coveros.training.library.domainobjects.Book book, com.coveros.training.library.domainobjects.Borrower borrower, java.sql.Date borrowDate) {
    if (book.id == 0) {
        com.coveros.training.library.LibraryUtils.logger.info("book: {} was not registered.  Lending failed", book.title);
        return com.coveros.training.library.domainobjects.LibraryActionResults.BOOK_NOT_REGISTERED;
    }
    if (borrower.id == 0) {
        com.coveros.training.library.LibraryUtils.logger.info("borrower: {} was not registered.  Lending failed", borrower.name);
        return com.coveros.training.library.domainobjects.LibraryActionResults.BORROWER_NOT_REGISTERED;
    }
    final com.coveros.training.library.domainobjects.Loan loan = searchForLoanByBook(book);
    if (!loan.isEmpty()) {
        com.coveros.training.library.LibraryUtils.logger.info("book: {} was already checked out on {}.  Lending failed", book.title, loan.checkoutDate);
        return com.coveros.training.library.domainobjects.LibraryActionResults.BOOK_CHECKED_OUT;
    }
    com.coveros.training.library.LibraryUtils.logger.info("book: {} is available for borrowing by valid borrower: {}", book.title, borrower.name);
    createLoan(book, borrower, borrowDate);
    return com.coveros.training.library.domainobjects.LibraryActionResults.SUCCESS;
}

/**
 * This is here so we can extract out the portion of code
 * that calls to the persistence layer, making it easier to test.
 */
void createLoan(com.coveros.training.library.domainobjects.Book book, com.coveros.training.library.domainobjects.Borrower borrower, java.sql.Date borrowDate) {
    com.coveros.training.library.LibraryUtils.logger.info("creating loan for book: {} by borrower: {}", book.title, borrower.name);
    persistence.createLoan(book, borrower, borrowDate);
}

/**
 * This is here so we can extract out the portion of code
 * that calls to the persistence layer, making it easier to test.
 */
void saveNewBorrower(java.lang.String borrower) {
    com.coveros.training.library.LibraryUtils.logger.info("saving new borrower: {}", borrower);
    persistence.saveNewBorrower(borrower);
}

/**
 * The id has to be positive.  Exception will be thrown otherwise.
 */
public com.coveros.training.library.domainobjects.Borrower searchForBorrowerById(long id) {
    if (id < 1) {
        throw new java.lang.IllegalArgumentException("when searching for a borrower, must include an id of one or greater");
    }
    com.coveros.training.library.LibraryUtils.logger.info("search for borrower with id: {}", id);
    final com.coveros.training.library.domainobjects.Borrower borrower = persistence.searchBorrowersById(id).orElse(com.coveros.training.library.domainobjects.Borrower.createEmpty());
    if (borrower.isEmpty()) {
        com.coveros.training.library.LibraryUtils.logger.info("No borrower found with id of {}", id);
    } else {
        com.coveros.training.library.LibraryUtils.logger.info("borrower found with id of {}", id);
    }
    return borrower;
}

