/**
 * Ackerman function.
 *
 * This version found at https://rosettacode.org/wiki/Ackermann_function#Java
 */
public static java.math.BigInteger ack(java.math.BigInteger m, java.math.BigInteger n) {
    if (m.equals(java.math.BigInteger.ZERO)) {
        return n.add(java.math.BigInteger.ONE);
    }
    if (n.equals(java.math.BigInteger.ZERO)) {
        return com.coveros.training.mathematics.Ackermann.ack(m.subtract(java.math.BigInteger.ONE), java.math.BigInteger.ONE);
    }
    return com.coveros.training.mathematics.Ackermann.ack(m.subtract(java.math.BigInteger.ONE), com.coveros.training.mathematics.Ackermann.ack(m, n.subtract(java.math.BigInteger.ONE)));
}

/**
 * A helper method to make it easy to call this with only integers
 * Calls to {@link #ack}
 */
public static java.math.BigInteger calculate(int m, int n) {
    java.math.BigInteger bigM = java.math.BigInteger.valueOf(m);
    java.math.BigInteger bigN = java.math.BigInteger.valueOf(n);
    return com.coveros.training.mathematics.Ackermann.ack(bigM, bigN);
}

