public static java.math.BigInteger fibAlgo2(int n) {
    if (n < 2) {
        return java.math.BigInteger.valueOf(n);
    }
    java.math.BigInteger ans = java.math.BigInteger.ZERO;
    java.math.BigInteger n1 = java.math.BigInteger.ZERO;
    java.math.BigInteger n2 = java.math.BigInteger.ONE;
    for (n--; n > 0; n--) {
        ans = n1.add(n2);
        n1 = n2;
        n2 = ans;
    }
    return ans;
}

/**
 * O(log(n))
 */
public static java.math.BigInteger fibAlgo1(long n) {
    if (n <= 0) {
        return java.math.BigInteger.ZERO;
    }
    java.math.BigInteger i = java.math.BigInteger.valueOf(n).subtract(java.math.BigInteger.ONE);
    java.math.BigInteger a = java.math.BigInteger.ONE;
    java.math.BigInteger b = java.math.BigInteger.ZERO;
    java.math.BigInteger c = java.math.BigInteger.ZERO;
    java.math.BigInteger d = java.math.BigInteger.ONE;
    java.math.BigInteger tmp1;
    java.math.BigInteger tmp2;
    while (i.compareTo(java.math.BigInteger.ZERO) > 0) {
        if (!i.mod(java.math.BigInteger.valueOf(2)).equals(java.math.BigInteger.ZERO)) {
            tmp1 = d.multiply(b).add(c.multiply(a));
            tmp2 = d.multiply(b.add(a)).add(c.multiply(b));
            a = tmp1;
            b = tmp2;
        }
        tmp1 = c.pow(2).add(d.pow(2));
        tmp2 = d.multiply(c.multiply(java.math.BigInteger.valueOf(2)).add(d));
        c = tmp1;
        d = tmp2;
        i = i.divide(java.math.BigInteger.valueOf(2));
    } 
    return a.add(b);
}

