/**
 * Converts an array of bytes to their corresponding hex string
 *
 * @param bytes
 * 		an array of bytes
 * @return a hex string of that array
 */
private static java.lang.String bytesToHex(byte[] bytes) {
    java.lang.StringBuilder hexString = new java.lang.StringBuilder();
    for (byte b : bytes) {
        java.lang.String hex = java.lang.Integer.toHexString(0xff & b);
        if (hex.length() == 1) {
            hexString.append('0');
        }
        hexString.append(hex);
    }
    return hexString.toString();
}

