/**
 * This wraps the throwing function, so that we are not forced to
 * catch an exception in our ordinary code - it's caught and handled
 * here.
 *
 * @param throwingFunction
 * 		a lambda that throws a checked exception we have to handle.
 * 		specifically in this case that's a SqlRuntimeException
 * @param <R>
 * 		the type of value returned
 * @return returns a function that runs and returns a function wrapped with an exception handler
 */
static <R> java.util.function.Function<java.sql.ResultSet, R> throwingFunctionWrapper(com.coveros.training.persistence.PersistenceLayer.ThrowingFunction<R, java.lang.Exception> throwingFunction) {
    return resultSet -> {
        try {
            return throwingFunction.apply(resultSet);
        } catch (java.lang.Exception ex) {
            throw new com.coveros.training.persistence.SqlRuntimeException(ex);
        }
    };
}

