/**
 * Given a password (for example, "password123"), return a
 * hash of that.
 *
 * @param password
 * 		a user's password
 * @return a hash of the password value.  a one-way function that returns a unique value,
but different than the original, cannot be converted back to its original value.
 */
private java.lang.String createHashedValueFromPassword(java.lang.String password) {
    com.coveros.training.helpers.CheckUtils.StringMustNotBeNullOrEmpty(password);
    try {
        java.security.MessageDigest digest = java.security.MessageDigest.getInstance("SHA-256");
        byte[] encodedhash = digest.digest(password.getBytes(java.nio.charset.StandardCharsets.UTF_8));
        return com.coveros.training.persistence.PersistenceLayer.bytesToHex(encodedhash);
    } catch (java.security.NoSuchAlgorithmException e) {
        throw new com.coveros.training.persistence.SqlRuntimeException(e);
    }
}

