 */
@org.junit.Test
public void test_shouldLendBook() {
    getPage("http://localhost:8080/demo/flyway");
    com.gargoylesoftware.htmlunit.html.HtmlPage page = getPage("http://localhost:8080/demo/library.html");
    type(page.getElementById("register_book"), "some book");
    page = click(page.getElementById("register_book_submit"));
    page = click(page.getAnchorByText("Return"));
    type(page.getElementById("register_borrower"), "some borrower");
    page = click(page.getElementById("register_borrower_submit"));
    page = click(page.getAnchorByText("Return"));
    type(page.getElementById("lend_book"), "some book");
    type(page.getElementById("lend_borrower"), "some borrower");
    page = click(page.getElementById("lend_book_submit"));
    final com.gargoylesoftware.htmlunit.html.DomElement result = page.getElementById("result");
    Assert.assertEquals("SUCCESS", result.getTextContent());
}

private com.gargoylesoftware.htmlunit.html.HtmlPage getPage(java.lang.String url) {
    try {
        return driver.getPage(url);
    } catch (java.lang.Exception ex) {
        throw new java.lang.RuntimeException(ex);
    }
}

private com.gargoylesoftware.htmlunit.html.HtmlPage click(com.gargoylesoftware.htmlunit.html.DomElement button) {
    try {
        return button.click();
    } catch (java.lang.Exception ex) {
        throw new java.lang.RuntimeException(ex);
    }
}

private void type(com.gargoylesoftware.htmlunit.html.DomElement input, java.lang.String text) {
    try {
        // try to send text assuming it's a text input...
        ((com.gargoylesoftware.htmlunit.html.HtmlTextInput) (input)).type(text);
    } catch (java.lang.Exception ex) {
        // if we fail *because* it's a password input
        if (ex.getMessage().contains("HtmlPasswordInput cannot be cast to class com.gargoylesoftware.htmlunit.html.HtmlTextInput")) {
            try {
                // try to use it as a password input.
                ((com.gargoylesoftware.htmlunit.html.HtmlPasswordInput) (input)).type(text);
            } catch (java.lang.Exception ex1) {
                throw new java.lang.RuntimeException(ex1);
            }
        }
    }
}

